/** JSON file imports. */
declare module '*.json' {
  const value: any;
  export default value;
}

/** SVG file imports. */
declare module '*.svg' {
  const value: any;
  export default value;
}

/** PNG file imports. */
declare module '*.png' {
  const value: any;
  export default value;
}

/** JPG file imports. */
declare module '*.jpg' {
  const value: any;
  export default value;
}

/** Font file imports */
declare module '*.woff';

